import * as yup from "yup";
export const userSchemaValidation = yup.object().shape({
  fullName: yup.string().min(3, "Full name must be at least 3 characters").required("Full name is required"),
  email: yup.string().email("Please enter a valid email address").required("Email is required"),
  password: yup.string().min(6, "Password must be at least 6 characters").matches(/[0-9]/, "Password must include at least one number").required("Password is required"),
  major: yup.string().notOneOf([""], "Please select your major").required("Major is required"),
  age: yup.number().typeError("Age must be a number").min(17, "Minimum age is 17").max(45, "Maximum age is 45").required("Age is required")
});
